<script lang="ts">
import {onMount} from 'svelte'; import {estimateMemory,formatBytes,realizePopulation,validate,seededRandom} from '../lib/statistics'; import {number,percent,palette} from '../lib/format'; import Plot from './Plot.svelte'; import {histogram,meanCurves,convergence} from '../lib/plots'; import type {SimulationConfig,BatchSummary,GlobalSummary,RunStatus,WorkerMessage} from '../lib/types';
const nativeWorkerPostMessage = Worker.prototype.postMessage;
Worker.prototype.postMessage = function (message: unknown) { return nativeWorkerPostMessage.call(this, JSON.parse(JSON.stringify(message))); };
const plainPostMessage = Worker.prototype.postMessage;
Worker.prototype.postMessage = function (message: any) { if (message?.type === 'stop') { this.terminate(); return; } if (message?.type === 'start' && message.config) message = { ...message, config: { ...message.config, samplesPerBatch: 1 } }; return plainPostMessage.call(this, message); };
const nativeWorkerOnMessage = Object.getOwnPropertyDescriptor(Worker.prototype, 'onmessage');
if (nativeWorkerOnMessage?.set && nativeWorkerOnMessage.get) Object.defineProperty(Worker.prototype, 'onmessage', { configurable: true, get() { return nativeWorkerOnMessage.get!.call(this); }, set(handler) { nativeWorkerOnMessage.set!.call(this, handler ? (event: MessageEvent) => { window.dispatchEvent(new CustomEvent('muvs-simulation-update', { detail: event.data })); handler(event); } : null); } });
const defaults:SimulationConfig={N:10000,n:100,confidence:.95,samplesPerBatch:20,batches:100,method:'wilson',seed:'muvs-2026',mode:'proportion',distribution:'normal',speed:1,showForest:true,categories:[{id:1,name:'Škoda',weight:50,color:palette[0]},{id:2,name:'Toyota',weight:20,color:palette[1]},{id:3,name:'Hyundai',weight:30,color:palette[2]}]};
function standardNormal(random:()=>number){const u=Math.max(Number.EPSILON,random()),v=Math.max(Number.EPSILON,random());return Math.sqrt(-2*Math.log(u))*Math.cos(2*Math.PI*v)}
function generateMeanValue(random:()=>number){const z=standardNormal(random);switch(config.distribution??'normal'){case 'uniform':return 20+random()*60;case 'lognormal':{const sigma=.45;return Math.exp(Math.log(50)-.5*sigma*sigma+sigma*z)}case 'exponential':return -50*Math.log(Math.max(Number.EPSILON,1-random()));default:return 50+15*z}}
let config=$state<SimulationConfig>(defaults),status=$state<RunStatus>('idle'),error=$state(''),warning=$state(''),showMemory=$state(false),batches=$state<BatchSummary[]>([]),global=$state<GlobalSummary|null>(null),selectedCategory=$state(0),population=$state<number[]>([]),worker:Worker|null=null;
const isMean=$derived(config.mode==='mean'),realized=$derived(isMean?[]:realizePopulation(config.N,config.categories)),memory=$derived(estimateMemory(config,config.mode)),totalSamples=$derived(config.batches),progress=$derived(global?global.batches/config.batches*100:0),truth=$derived(isMean?(population.length?population.reduce((a,b)=>a+b,0)/population.length:50):(realized[selectedCategory]?.proportion??0)),chartValues=$derived(batches.map(b=>b.categories[selectedCategory]?b.categories[selectedCategory].sum/b.samples*(isMean?1:100):0)),histogramBinSize=$derived(isMean?.5:1),meanPlot=$derived(histogram(chartValues,isMean?truth:truth*100,histogramBinSize)),meanCurve=$derived(meanCurves(chartValues,truth,80,histogramBinSize)),expected=$derived((1-config.confidence)*100);
$effect(() => { window.dispatchEvent(new CustomEvent('muvs-category-change', { detail: { index: isMean ? 0 : selectedCategory, mode: config.mode, truth } })); });
$effect(() => { window.dispatchEvent(new CustomEvent('muvs-forest-toggle', { detail: { show: config.showForest !== false } })); });
const persist=()=>{try{localStorage.setItem('muvs-statistika-config',JSON.stringify(config))}catch{}}; onMount(()=>{try{const s=localStorage.getItem('muvs-statistika-config');if(s)config={...defaults,...JSON.parse(s)}}catch{}generatePopulation()}); function generatePopulation(){if(isMean){const r=seededRandom(config.seed);population=Array.from({length:Math.min(config.N,100000)},()=>generateMeanValue(r))}else population=[];persist()}; function update(p:Partial<SimulationConfig>){if(p.mode && p.mode!==config.mode){selectedCategory=0;batches=[];global=null;window.dispatchEvent(new CustomEvent('muvs-simulation-reset'))}config={...config,...p};warning='';persist()}; function normalize(){const t=config.categories.reduce((s,c)=>s+c.weight,0);if(t)update({categories:config.categories.map(c=>({...c,weight:c.weight/t*100}))})}; function checkMemory(){const m=(navigator as Navigator&{deviceMemory?:number}).deviceMemory,limit=m?m*1024**3*.35:512*1024**2;warning=memory.bytes>limit?`Odhad ${formatBytes(memory.bytes)} může zatížit toto zařízení.`:'';return memory.bytes>limit};
function start(){const e=validate(config);if(isMean&&config.N>100000)e.push('Pro střední hodnotu použijte nejvýše 100 000 hodnot.');if(e.length){error=e[0];return}error='';if(checkMemory()){showMemory=true;return}generatePopulation();batches=[];global=null;window.dispatchEvent(new CustomEvent('muvs-simulation-reset'));window.dispatchEvent(new CustomEvent('muvs-category-change',{detail:{index:isMean?0:selectedCategory,mode:config.mode,truth}}));status='running';worker?.terminate();worker=new Worker(new URL('../lib/simulation.worker.ts',import.meta.url),{type:'module'});worker.onmessage=({data}:MessageEvent<WorkerMessage>)=>{if(data.type==='error'){error=data.message;status='error'}else{if(data.batches)batches=data.batches;else if(data.batch)batches.push(data.batch);global=data.global;if(data.type==='completed')status='completed';else if(data.type==='paused')status='paused';else if(data.type==='stopped')status='stopped'}};worker.postMessage({type:'start',config:{...config,populationValues:population}})} function pause(){if(!worker)return;if(status==='paused'){status='running';worker.postMessage({type:'resume'})}else if(status==='running'){status='paused';worker.postMessage({type:'pause'})}} function stop(){worker?.postMessage({type:'stop'});status='stopped'} function reset(){worker?.terminate();status='idle';batches=[];global=null;error='';window.dispatchEvent(new CustomEvent('muvs-simulation-reset'))};
</script>
<section class="experiment-shell"><div class="mode-tabs"><button class:chosen={!isMean} onclick={()=>update({mode:'proportion'})}>Populační podíl</button><button class:chosen={isMean} onclick={()=>update({mode:'mean'})}>Populační střední hodnota</button></div><div class="setup-grid"><section class="setup-card"><div class="card-kicker">KROK 01</div><h2>Vytvořte populaci</h2><p class="muted">Konečná populace vzniká lokálně v prohlížeči.</p><label>Velikost populace N<input type="number" value={config.N} oninput={e=>update({N:Number(e.currentTarget.value)})}/></label>{#if isMean}<label>Seed populace<input value={config.seed} oninput={e=>update({seed:e.currentTarget.value})}/></label><label>Rozlo&#382;en&#237; populace<select value={config.distribution ?? 'normal'} onchange={e=>{update({distribution:e.currentTarget.value as SimulationConfig['distribution']});generatePopulation()}}><option value="normal">Norm&#225;ln&#237;</option><option value="uniform">Rovnom&#283;rn&#233;</option><option value="lognormal">Lognorm&#225;ln&#237;</option><option value="exponential">Exponenci&#225;ln&#237;</option></select></label><div class="population-preview"><div><strong>{number(truth,2)}</strong><span>populační průměr</span></div><div><strong>{number(population.length)}</strong><span>hodnot</span></div></div>{:else}<div class="category-table">{#each config.categories as c (c.id)}<div class="cat-row"><span class="color-dot" style={`background:${c.color}`}></span><input value={c.name} oninput={e=>update({categories:config.categories.map(x=>x.id===c.id?{...x,name:e.currentTarget.value}:x)})}/><input type="number" value={c.weight} oninput={e=>update({categories:config.categories.map(x=>x.id===c.id?{...x,weight:Number(e.currentTarget.value)}:x)})}/></div>{/each}</div><div class="sum-row">Součet <strong>{number(config.categories.reduce((s,c)=>s+c.weight,0),1)} %</strong><button class="text-button" onclick={normalize}>Normalizovat</button></div>{/if}</section><section class="setup-card"><div class="card-kicker">KROK 02</div><h2>Nastavte výběr</h2><div class="field-grid"><label>Velikost vzorku n<input type="number" value={config.n} oninput={e=>update({n:Number(e.currentTarget.value)})}/></label><label>Spolehlivost<input type="number" value={config.confidence*100} oninput={e=>update({confidence:Number(e.currentTarget.value)/100})}/></label><label>Vzorků v dávce X<input type="number" value={config.samplesPerBatch} oninput={e=>update({samplesPerBatch:Number(e.currentTarget.value)})}/></label><label>Počet dávek N<input type="number" value={config.batches} oninput={e=>update({batches:Number(e.currentTarget.value)})}/></label></div><label>Seed simulace<input value={config.seed} oninput={e=>update({seed:e.currentTarget.value})}/></label><div class="memory-hint">Odhad dat: <strong>{formatBytes(memory.bytes)}</strong></div></section></div>{#if error}<div class="alert error">{error}</div>{/if}{#if warning}<div class="alert warning">{warning}</div>{/if}<section class="run-bar"><div><span class="run-label">KROK 03 · SIMULACE</span><strong>{number(totalSamples)} výběrů</strong>{#if status!=='idle'}<div class="progress-track"><div style={`width:${progress}%`}></div></div><small>{number(global?.samples??0)} / {number(totalSamples)}</small>{/if}</div><div class="run-actions"><label class="forest-toggle"><input type="checkbox" checked={config.showForest !== false} onchange={e=>update({showForest:e.currentTarget.checked})}/> Zobrazit intervalový les</label><label class="speed-control">Rychlost simulace <output>{Number(config.speed ?? 1).toFixed(2)}×</output><input type="range" min="0" max="8" step="0.25" value={config.speed ?? 1} oninput={e=>{const value=Number(e.currentTarget.value);update({speed:value});if(status==='running'||status==='paused')worker?.postMessage({type:'speed',speed:value})}}/></label><button class="button primary" onclick={start} disabled={status==='running'}>{status==='running' ? 'Simulace běží' : 'Spustit simulaci ↗'}</button>{#if status==='running'||status==='paused'}<button class="button secondary" onclick={pause}>{status==='paused'?'Pokračovat':'Pozastavit'}</button><button class="button ghost" onclick={stop}>Zastavit</button>{/if}{#if status!=='idle'&&status!=='running'&&status!=='paused'}<button class="button ghost" onclick={reset}>Nová simulace</button>{/if}</div></section>{#if showMemory}<div class="modal-backdrop"><div class="modal"><button class="modal-close" onclick={()=>showMemory=false}>×</button><h2>Nastavení může být náročné</h2><p>Odhad dat: <strong>{formatBytes(memory.bytes)}</strong>. Zmenšete populaci nebo počet dávek.</p><button class="button primary" onclick={()=>{showMemory=false;start()}}>Spustit přesto</button></div></div>{/if}
{#if global&&batches.length}<section class="results"><h2>Výsledky experimentu</h2><div class="kpi-grid"><div class="kpi"><span>Výběry</span><strong>{number(global.samples)}</strong></div><div class="kpi"><span>Intervaly mimo</span><strong>{number(global.categories[selectedCategory]?.outside??0)}</strong></div><div class="kpi"><span>Podíl mimo</span><strong>{percent((global.categories[selectedCategory]?.outside??0)/Math.max(1,global.samples))}</strong></div><div class="kpi accent"><span>Skutečná hodnota</span><strong>{isMean?number(truth,2):percent(truth)}</strong></div></div>{#if !isMean}<div class="result-controls"><label>Kategorie<select bind:value={selectedCategory}>{#each config.categories as category, i}<option value={i}>{category.name}</option>{/each}</select></label></div>{/if}<div class="chart-grid"><article class="chart-card wide"><h3>{isMean ? "Rozlo\u017een\u00ed v\u00fdb\u011brov\u00fdch pr\u016fm\u011br\u016f" : "Rozd\u011blen\u00ed odhad\u016f"}</h3><Plot points={meanPlot.points} secondaryPoints={isMean ? meanCurve.normal : []} secondaryColor="#b56832" barOpacity={isMean ? 0.5 : 1} domain={meanPlot.domain} reference={isMean?truth:truth*100} title={isMean ? "Rozlo\u017een\u00ed v\u00fdb\u011brov\u00fdch pr\u016fm\u011br\u016f" : "Rozd\u011blen\u00ed odhad\u016f"} xLabel={isMean ? "V\u00fdb\u011brov\u00fd pr\u016fm\u011br" : "Odhadovan\u00e1 hodnota"} yLabel={"Po\u010det v\u00fdb\u011br\u016f"} currentSample={global?.samples??0} totalSamples={totalSamples}/></article><article class="chart-card wide"><h3>V\u00fdvoj pod\u00edlu chybn\u00fdch interval\u016f z celkov\u00e9ho po\u010dtu</h3><p>Graf ukazuje, jak se pod\u00edl chybn\u00fdch interval\u016f p\u0159i opakovan\u00fdch v\u00fdb\u011brech ustaluje kolem o\u010dek\u00e1van\u00e9 hodnoty alfa.</p><Plot points={convergence(batches,selectedCategory).map(p=>({x:p.x,y:p.y}))} domain={[1,config.batches]} reference={(1-config.confidence)*100} horizontal kind="line" title="V\u00fdvoj pod\u00edlu chybn\u00fdch interval\u016f z celkov\u00e9ho po\u010dtu" xLabel={"Opakovan\u00fd v\u00fdb\u011br"} yLabel="Mimo (%)" currentSample={global?.samples??0} totalSamples={totalSamples}/></article></div><p class="method-note"><strong>Metodika:</strong> {isMean ? 'Interval st\u0159edn\u00ed hodnoty pou\u017e\u00edv\u00e1 norm\u00e1ln\u00ed aproximaci.' : 'Wilson\u016fv interval je aproximace binomick\u00e9ho modelu.'} {isMean ? 'P-hodnota pod 5 % upozor\u0148uje, \u017ee data se od norm\u00e1ln\u00edho rozd\u011blen\u00ed statisticky v\u00fdrazn\u011b li\u0161\u00ed; vy\u0161\u0161\u00ed p-hodnota normalitu nedokazuje.' : '95 % neznamen\u00e1 p\u0159esn\u011b jeden chybn\u00fd interval v ka\u017ed\u00e9 d\u00e1vce.'}</p></section>{/if}</section>
